import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

// The pre-0.14 aces plugins injected their own HTTP MCP servers into every
// agent's saved config and provider session metadata:
//
//   config.mcpServers["aces-boards"]            = { type: "http", url: "http://127.0.0.1:<port>/mcp" }
//   persistence.metadata.mcpServers["aces-*"]  = (same)
//
// Those URLs go stale when the plugin is disabled/reloaded/upgraded, and the
// dead servers make the agent's provider fail to reconnect. The current plugins
// attach tools with defineAgentTool and never save an MCP URL, so anything that
// still references the old keys is a stale leftover worth cleaning up.

const ACES_MCP_KEYS = ["aces-boards", "aces-teammates"] as const;

export function acesHome(): string {
  return process.env.PASEO_HOME || join(homedir(), ".paseo");
}

function walk(dir: string): string[] {
  const out: string[] = [];
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    let st;
    try {
      st = statSync(p);
    } catch {
      continue;
    }
    if (st.isDirectory()) out.push(...walk(p));
    else if (name.endsWith(".json")) out.push(p);
  }
  return out;
}

// Recursively delete `aces-boards` / `aces-teammates` entries from every
// `mcpServers` object in the record. Returns true when it removed anything.
// Used both to detect (on a throwaway parse) and to clean (on the real parse).
function stripAcesMcp(node: unknown): boolean {
  if (!node || typeof node !== "object") return false;
  let changed = false;
  for (const key of Object.keys(node as Record<string, unknown>)) {
    const value = (node as Record<string, unknown>)[key];
    if (key === "mcpServers" && value && typeof value === "object" && !Array.isArray(value)) {
      const servers = value as Record<string, unknown>;
      let removed = false;
      for (const k of ACES_MCP_KEYS) {
        if (k in servers) {
          delete servers[k];
          removed = true;
        }
      }
      if (removed) {
        changed = true;
        if (Object.keys(servers).length === 0) {
          delete (node as Record<string, unknown>)[key];
        }
      }
    } else if (value && typeof value === "object") {
      if (stripAcesMcp(value)) changed = true;
    }
  }
  return changed;
}

// The two locations that can carry a stale aces MCP reference in a way that
// actually re-injects it: the agent records and the schedule targets. Creation
// lifecycle records only carry the references inside inert fingerprints, so
// they are intentionally excluded.
function staleFiles(): string[] {
  const roots = ["agents", "schedules"].map((d) => join(acesHome(), d));
  const files: string[] = [];
  for (const root of roots) {
    for (const file of walk(root)) {
      let obj: unknown;
      try {
        obj = JSON.parse(readFileSync(file, "utf8"));
      } catch {
        continue;
      }
      if (stripAcesMcp(obj)) files.push(file);
    }
  }
  return files;
}

export interface StaleScanResult {
  count: number;
  files: string[];
}

export function scanStaleAcesMcp(): StaleScanResult {
  const files = staleFiles();
  return { count: files.length, files };
}

export function cleanStaleAcesMcp(): { cleaned: number } {
  let cleaned = 0;
  for (const file of staleFiles()) {
    try {
      const obj = JSON.parse(readFileSync(file, "utf8"));
      if (stripAcesMcp(obj)) {
        writeFileSync(file, JSON.stringify(obj, null, 2) + "\n", "utf8");
        cleaned++;
      }
    } catch {
      // Ignore unreadable records; report what we could clean.
    }
  }
  return { cleaned };
}
